-- 将外部收集的 350 条候选事项按 docs/activity-admission-standard.md 筛选、去重和重写。
-- 保留原有 21 条，新增首批 79 条候选事项。
-- 注意：“100 件”是家庭侧目标，不是 public.levels 候选库的数量上限。
-- source_id 仅用于追溯 /home/coder/workspaces/亲子100件小事_数据源.json，不写入业务表。

BEGIN;

WITH curated(source_id, num, perspective, tone, title, why, how, record, suggest, seasonal, sort_order) AS (
  VALUES
  (2,   '01', 'together', 'pink',   '一起整理一本真正会翻看的家庭相册', '挑选照片的过程，会让孩子知道：那些看似普通的日子，也一直被家人珍惜。', '从最近一年选十几张照片，每个人各挑最喜欢的几张，并说说为什么。做成纸质或电子相册都可以。', '拍下孩子指着某张照片讲故事的样子，再记下他选它的理由。', 'photo', false, 22),
  (159, '06', 'together', 'orange', '拍一张由孩子决定姿势的全家福', '当孩子也能决定一家人如何被记住，合影就不只是摆拍，而是共同创作。', '找一个大家都不赶时间的日子，让孩子选地点、站位和动作；不要求整齐，也不纠正表情。', '留下正式合影之外最好笑或最自然的那一张。', 'photo', false, 23),
  (298, '10', 'parent',   'green',  '陪孩子重看成长照片，讲出照片外的故事', '照片保存了样子，你讲出的担心、惊喜和细节，才会让孩子理解自己怎样被爱着长大。', '让孩子随意挑五张旧照片，你只讲当时真实发生的小事，也邀请他猜猜那时的自己。', '录下其中一段最想留给未来再听的讲述。', 'voice', false, 24),
  (341, '16', 'together', 'pink',   '在家里留下这一年的身高刻度', '一条小小的刻度，会把看不见的成长变成多年后仍能触摸的时间。', '选一面可长期保留的墙或一张身高记录纸，互相量身高，写上日期和当下的小愿望。', '拍下孩子站在刻度旁的全身照，并记下当天的愿望。', 'photo', false, 25),
  (301, '20', 'together', 'orange', '共同写下一页家庭日记', '同一天在大人和孩子眼里常常完全不同，把两种视角放在一起就是珍贵的家庭史。', '选一个普通日子，各写或画一件今天最想记住的事；不会写字就让孩子口述。', '保存这一页，并标出你们不约而同写到的细节。', 'photo', false, 26),
  (161, '22', 'parent',   'green',  '给孩子讲讲你们成为一家人之前的故事', '孩子认识的不只是“爸爸妈妈”，也会看见两个普通人怎样相遇、选择并慢慢成为家人。', '借几张旧照片或一段婚礼影像，讲真实、有趣且适合孩子年龄的片段，不必把故事讲得完美。', '录下孩子听完后最想追问的那个问题。', 'voice', false, 27),
  (303, '24', 'together', 'pink',   '互相写一封现在就想收到的小信', '有些爱当面说不完整，写下来会成为以后低落时仍能重新打开的力量。', '各自写几句话或画一张卡片，只写欣赏、感谢和想一起做的事，不评价对方哪里需要改。', '把两封信放在一起拍下来，约定以后再读一次。', 'photo', false, 28),
  (315, '26', 'parent',   'orange', '认真告诉孩子：我爱你，也喜欢真实的你', '不和表现挂钩的爱，会成为孩子面对外面世界时最稳的安全感。', '找一个安静的时刻，看着孩子说清楚爱不是奖励；再具体说一件你最近欣赏他的地方。', '写下当时你说的话和孩子的反应，不必要求他回应。', 'text', false, 29),
  (240, '28', 'child',    'green',  '让孩子带你走进他在学校的一天', '被认真听见，比被追问成绩更能让孩子愿意持续分享自己的世界。', '从“今天哪个瞬间最好玩”开始，只听不审问；孩子不想聊的部分可以跳过。', '记下一个你原本不知道的人、地方或小插曲。', 'text', false, 30),
  (38,  '30', 'child',    'pink',   '聊一次不需要马上实现的梦想', '梦想不必合理才值得被听见；你的好奇和尊重，会保护孩子想象未来的勇气。', '你们轮流说三个想做、想成为或想看见的愿望，只问“为什么喜欢”，先不讨论可不可行。', '录下孩子描述梦想时最有画面感的一段话。', 'voice', false, 31),
  (42,  '32', 'together', 'orange', '开一次每个人都有一票的家庭会议', '当孩子的意见能真正影响家庭决定，他会更懂得表达、倾听和共同负责。', '选一个真实但不沉重的议题，比如周末安排或家中规则；轮流发言，最后说明决定怎样形成。', '写下议题、每个人的提议和最后的共同决定。', 'text', false, 32),
  (166, '33', 'together', 'green',  '全家放下电子设备，过半天慢一点的生活', '没有通知打断的共同时间，会让一家人重新发现彼此真正喜欢怎样待在一起。', '共同约定一个可承受的时长，把设备放进盒子；由每个人各选一件想一起做的小事。', '结束后各写一句：没有屏幕时，我最喜欢的时刻是。', 'text', false, 33),
  (170, '34', 'together', 'pink',   '创造一个只属于你们家的年度节日', '家庭文化常常来自共同发明的小传统，它会让孩子在很多年后仍知道“我们家是什么样”。', '一起定名字、日期和一个简单仪式，例如做同一道菜或去同一处散步，规则越容易延续越好。', '记录节日名字、三条规则和第一届的合影。', 'photo', false, 34),
  (157, '35', 'together', 'orange', '一起设计一块代表这个家的门牌', '共同决定家的名字和符号，会把住所变成更有归属感的“我们的地方”。', '用纸板、木片或电子绘图设计门牌，让每个人贡献一个颜色、图案或词语。', '拍下门牌挂起或摆好的那一刻，并记下每个元素是谁选的。', 'photo', false, 35),
  (164, '36', 'together', 'green',  '一起搭一个让人想坐下来的阅读角', '孩子参与创造的空间，更可能成为他主动靠近书和家人的地方。', '不用添置昂贵家具，选一个角落，一起调整光线、坐垫和几本想共享的书。', '拍下改造前后，再记录第一本在这里一起读完的书。', 'photo', false, 36),
  (207, '37', 'child',    'pink',   '让孩子在图书馆为你挑一本书', '当大人认真读孩子选的书，孩子会感到自己的品味和判断被尊重。', '各自替对方挑一本能读完的书，先不干涉选择；找个位置互相读一小段。', '拍下交换后的两本书，并写一句彼此的推荐理由。', 'photo', false, 37),
  (337, '38', 'child',    'orange', '在博物馆请孩子当一次小小讲解员', '把“看懂多少”换成“你看见了什么”，孩子会从参观者变成有观点的发现者。', '让孩子自己选一件展品，给几分钟观察后讲给你听；不知道史实也可以说想象和感受。', '录下这段独一无二的讲解，最后请小讲解员为展品起个别名。', 'voice', false, 38),
  (310, '39', 'together', 'green',  '在科技馆一起弄懂一个装置', '共同承认“不知道”并动手寻找答案，比替孩子讲解更能保护好奇心。', '不要赶着打卡全馆，只选一个大家都好奇的装置，轮流猜原理、操作并读说明验证。', '拍下装置，并记下你们最初的猜想和最后的发现。', 'photo', false, 39),
  (212, '40', 'child',    'pink',   '看一场展览，各自选出最喜欢的一件作品', '审美没有标准答案，交换选择能让你们看见彼此不同的感受和想象。', '各自安静看一会儿，再带对方去看自己的选择，只说它让你想到什么，不考作品知识。', '给两件入选作品各写一句只有你们懂的观展评语。', 'text', false, 40),
  (308, '41', 'together', 'orange', '看一场现场演出，散场后交换一个瞬间', '共同经历过的灯光、声音和情绪，会成为比“看过什么”更长久的记忆。', '选择适龄的话剧、木偶戏或音乐会；散场后每个人只分享一个最难忘的画面或声音。', '录一段散场后的对话，保存彼此选中的瞬间。', 'voice', false, 41),
  (336, '42', 'together', 'green',  '看一场比赛，找出比分之外的体育精神', '胜负会过去，但坚持、合作和尊重对手的瞬间值得孩子真正看见。', '现场或转播都可以，赛前各选一方；赛后不只谈输赢，各找一个欣赏的动作或态度。', '写下你们各自选出的“今天最有力量的一刻”。', 'text', false, 42),
  (296, '43', 'together', 'pink',   '看完一部好电影，认真聊十分钟', '故事提供了一个安全的距离，让亲子能谈选择、害怕、善意和彼此不同的看法。', '共同选一部适龄电影，结束后轮流回答：最喜欢谁、哪次选择最难、如果是你会怎样。', '录下一个彼此答案完全不同的问题。', 'voice', false, 43),
  (306, '44', 'together', 'orange', '在地球仪上随机认识一个陌生国家', '一起探索未知，会让孩子感到世界很大，而学习可以从一个偶然的问题开始。', '闭眼指一个国家，各自负责找一个有趣事实：自然、食物、语言或孩子生活，最后互相讲。', '在地图上标记它，写下最想亲眼去看的一个地方。', 'text', false, 44),
  (149, '45', 'together', 'green',  '追查一件日常物品是怎样被发明的', '熟悉的东西背后藏着许多次失败和改进，能让孩子理解创造来自持续解决问题。', '让孩子从家里选一样物品，先猜没有它时人们怎么办，再一起查可靠资料验证。', '画或写一张“它出现以前—现在—未来”的小卡片。', 'photo', false, 45),
  (265, '46', 'together', 'pink',   '在夜空或天文馆找到北斗七星和北极星', '一起抬头寻找遥远而稳定的星星，会给普通夜晚留下清晰的坐标。', '选择天气晴朗且安全的观察地点，或去天文馆；先找北斗，再沿指向找到北极星，不必追求一次成功。', '拍下观察地点的夜色，写下是谁先找到、当时说了什么。', 'text', false, 46),
  (267, '47', 'together', 'orange', '带上画本，画同一棵树或同一座桥', '面对同一个景物画出不同答案，会让孩子直观看见观察没有唯一标准。', '各自画十到二十分钟，不互相指导也不比较像不像；完成后交换说最喜欢对方哪一处。', '把两幅画并排拍下，写上地点和日期。', 'photo', false, 47),
  (249, '48', 'together', 'green',  '收集落叶，做一页会变老的自然标本', '一片普通叶子经过寻找、辨认和保存，会成为你们共同观察季节的证据。', '只捡落叶，不折活枝；选形状不同的几片，压平后查名字并贴进纸页。', '拍下完成的标本页，再各自圈出最喜欢的一片。', 'photo', true, 48),
  (269, '49', 'together', 'pink',   '连续记录一株植物从花苞到凋谢', '一起等待细微变化，能让孩子感受生命不是瞬间完成，也练习真正的耐心。', '选一株容易观察的开花植物，每周同一角度看一次、拍一次，不催促它按预期变化。', '把第一张和最后一张并排保存，并写下最意外的变化。', 'photo', true, 49),
  (288, '50', 'together', 'orange', '用儿童显微镜看一次肉眼看不见的世界', '当熟悉的叶片或洋葱变成陌生纹理，好奇心会从答案重新回到问题。', '在成人看护下准备安全样本，先画出肉眼所见，再轮流观察；不接触不明液体或尖锐器材。', '拍下两幅“观察前后”的画，记下孩子冒出的第一个问题。', 'photo', false, 50),
  (277, '51', 'together', 'green',  '种一盆能端上餐桌的香草或蔬菜', '从照料到收获再到分享食物，孩子会看见耐心、责任和日常生活彼此相连。', '选适合当地环境的小葱、薄荷或番茄，让孩子负责一项固定照料；收获时一起决定怎么吃。', '记录播种、第一次发芽和第一次入口的三个瞬间。', 'photo', true, 51),
  (181, '52', 'child',    'pink',   '去田园里请孩子找出食物长大的地方', '亲眼看见米、菜和果实从哪里来，会让餐桌上的“应该珍惜”有真实依据。', '选择正规开放的农场或田园，由孩子寻找三种作物并猜食用的是哪一部分，尊重种植规则。', '让孩子选一种作物，录下他从田里到餐桌的讲解。', 'voice', true, 52),
  (263, '53', 'together', 'orange', '安静观察一次湿地里的水鸟', '为了不惊扰另一个生命而放轻声音，是自然教育里很温柔的一课。', '在正规步道保持距离观察，可借望远镜；不投喂、不追赶，各自找一只最想了解的鸟。', '画下或写下它的颜色、动作和你们给它起的临时名字。', 'text', true, 53),
  (266, '54', 'together', 'green',  '在地质馆挑一块最像“时间”的石头', '石头把遥远年代带到眼前，也让孩子理解世界的变化远比人的一生漫长。', '不求看完所有展品，各自挑一块最吸引自己的矿石或化石，读说明后讲讲它经历过什么。', '拍下两块选择，并写下它们大约来自多久以前。', 'photo', false, 54),
  (186, '55', 'child',    'pink',   '蹲下来观察池塘边的微小生命', '慢下来寻找蝌蚪、水黾或蜻蜓，会让孩子发现自然不只属于宏大的风景。', '只在有护栏或安全岸边观察，成人全程陪同；不下水、不捕捉，让孩子决定观察谁。', '记下一种小动物的动作，回家后再一起查它的名字。', 'text', true, 55),
  (196, '56', 'together', 'orange', '一起完成一次适合孩子参与的志愿服务', '共同为陌生人或社区做一点实事，善意就从抽象道理变成亲手完成的经验。', '选择正规机构和适龄任务，例如整理物资或社区清洁；先解释服务对象，并尊重孩子意愿。', '不拍受助者正脸，只记录你们完成的工作和各自的一点感受。', 'text', false, 56),
  (109, '57', 'child',    'green',  '让孩子挑出真正愿意分享的旧书', '捐赠不是替孩子清理物品，而是学习在有选择权的前提下分享珍惜过的东西。', '说明书会去哪里，让孩子自主挑选品相完好的书并擦净；舍不得的可以保留，不强迫数量。', '在箱子里放一张给下一位小读者的简短留言。', 'photo', false, 57),
  (346, '58', 'together', 'pink',   '办一次小小家庭义卖，把收入送去需要的地方', '孩子能同时经历整理、定价、沟通与捐赠，理解金钱也可以用来照顾他人。', '选择合规的社区场景和少量闲置物品，共同定价；事先选定可信捐赠渠道并公开核对金额。', '记录卖出的第一件物品、最终金额和捐赠去向。', 'photo', false, 58),
  (231, '59', 'child',    'orange', '为一位朋友准备一份“我懂你”的小礼物', '真正用心的礼物来自观察对方，而不是价格，它帮助孩子练习理解和表达友情。', '先聊朋友最近喜欢或需要什么，再共同制作或挑选；让孩子写下为什么觉得它适合对方。', '送出前拍下礼物和那张理由小卡片。', 'photo', false, 59),
  (230, '60', 'child',    'green',  '请孩子做主人，招待一次自己的朋友', '在被信任的主场里，孩子会练习计划、分享、照顾客人和处理小分歧。', '和孩子共同确定人数、活动和简单点心，让他负责欢迎与介绍；成人只在需要时帮助。', '结束后问小主人：哪件事比想象中难，哪件最自豪。', 'voice', false, 60),
  (234, '61', 'parent',   'pink',   '走一段路，让孩子来提醒全家看红绿灯', '真实道路上的反复判断，比一次安全说教更容易变成保护自己的习惯。', '选择熟悉且设施完善的路口，成人始终做最终判断；请孩子说出停、看、听和确认车辆的过程。', '回家后一起画出刚才经过的路口和安全路线。', 'photo', false, 61),
  (237, '62', 'parent',   'orange', '用角色游戏练习拨打 110、119 和 120', '紧急时能说清“发生什么、在哪里、我是谁”，是孩子真正可用的安全能力。', '先讲明三个号码的用途和不能恶作剧，再用玩具电话模拟三种情境；不要实际拨通测试。', '录下孩子最完整的一次模拟求助，之后一起补充遗漏信息。', 'voice', false, 62),
  (236, '63', 'child',    'green',  '把家人电话和家庭地址变成孩子会用的信息', '记住关键信息，并知道什么时候告诉可信任的大人，能在走失或紧急时提供真实保护。', '用儿歌、卡片或情境游戏分几次练习，同时说明不要随意向陌生人透露隐私。', '请孩子在模拟走失情境中完整说一遍，再记录仍需练习的部分。', 'voice', false, 63),
  (241, '64', 'together', 'pink',   '到常去的商场一起找到服务台和安全出口', '提前认识可以求助的人和地方，会让孩子在意外走散时少一点慌张。', '正常逛商场时顺路完成：找服务台、安全出口和工作人员标识，并约定走散后的等待规则。', '让孩子画一张“我会去哪里求助”的小地图。', 'photo', false, 64),
  (242, '65', 'parent',   'orange', '一起排查家里水、火、电的三个危险点', '安全规则来自共同发现和真实改进，比“不要碰”更容易被理解和记住。', '按孩子年龄查看插座、热水、燃气或尖锐物；解释原因并立即完成一项可见的防护改进。', '拍下改进前后，并请孩子说出一条他会提醒家人的规则。', 'voice', false, 65),
  (105, '66', 'together', 'green',  '一起整理家庭医药箱，认识“药不能自己拿”', '认识药品边界和过期日期，能把生活管理与最基本的用药安全连接起来。', '成人负责接触和处置药品，孩子帮忙看日期标识、分类非药品物资；过期药按当地要求回收。', '做好一张“谁能拿、放哪里、何时检查”的医药箱卡片。', 'photo', false, 66),
  (293, '67', 'together', 'pink',   '一起给自行车打气，做一次出发前检查', '亲手维护常用工具，会让孩子理解安全和顺利不是理所当然，而是有人认真准备。', '在成人看护下检查轮胎、刹车、车铃和头盔；工具由成人示范，孩子只做适龄步骤。', '拍下检查清单和完成后第一次安全骑行的出发照。', 'photo', false, 67),
  (254, '68', 'child',    'orange', '看着地图，步行去一个没走过的近处', '让孩子参与辨路和修正路线，一段熟悉城市里的小路也能成为真正的共同探险。', '选择安全、距离适龄的目的地，让孩子在岔路口读地图并做选择；成人负责交通和体力边界。', '保存走过的路线，并标出一次走错或临时改变的地方。', 'photo', false, 68),
  (247, '69', 'child',    'green',  '坐公交或地铁去一个不熟悉的街区散步', '公共交通把城市打开给孩子，也让他练习观察路线、礼让和在陌生环境中保持联系。', '共同选一个安全目的地，请孩子负责数站或认出口；全程遵守乘车规则，不把赶时间当挑战。', '记下孩子在新街区第一个发现的有趣细节。', 'text', false, 69),
  (108, '70', 'child',    'pink',   '去菜市场，让孩子为一顿饭挑选食材', '从挑选到端上餐桌，孩子会更具体地理解食物、预算和家庭劳动。', '先确定一道简单菜和预算，让孩子询价、比较并选一两样食材；成人处理支付和食品安全。', '拍下“市场里的食材”和“餐桌上的成品”两张对照照。', 'photo', false, 70),
  (252, '71', 'together', 'orange', '一起看懂家庭一周的钱花去了哪里', '透明而不过度焦虑地谈生活开支，能让孩子理解选择、需要和家庭共同承担。', '只用几个孩子能懂的类别和大致金额，不让孩子背负经济压力；一起找一项想调整的小支出。', '画一张简单的开支图，并写下你们共同做出的一个选择。', 'photo', false, 71),
  (115, '72', 'child',    'green',  '让孩子为一笔压岁钱做自己的分配计划', '被允许规划真实的钱，孩子才会在选择和等待中逐渐形成金钱判断。', '把钱分成使用、储蓄和分享等部分，让孩子先提方案；家长只说明边界，不替他决定每一笔。', '保存这份分配计划，几个月后一起回看是否仍认同。', 'text', false, 72),
  (199, '73', 'child',    'pink',   '在商店完成一次有预算的自主付款', '真实选择、算价和付款，会让孩子理解钱与物品之间的关系，而不只是认识数字。', '给一个小额明确预算，让孩子比较后选择并在成人陪同下付款；买或不买都尊重他的决定。', '记录原预算、实际花费和孩子放弃的一个选择。', 'text', false, 73),
  (203, '74', 'child',    'orange', '由孩子决定怎样处理不再玩的玩具', '告别物品也是成长：他会练习判断需要、尊重回忆，并让闲置重新产生价值。', '分成保留、赠送、出售和待决定四类，决定权尽量交给孩子；有情感的物品不催促处理。', '请孩子为最舍不得但最终放手的一件玩具留张照片和一句话。', 'photo', false, 74),
  (39,  '75', 'together', 'green',  '为一个共同愿望画出攒钱路线', '一起等待和取舍，会让“想要”从即时满足变成可讨论、可合作的计划。', '选择金额适中且全家认同的目标，画出进度格；约定钱从哪里来，也允许中途重新评估目标。', '保存第一天的目标卡，并在完成时写下这段等待教会了什么。', 'photo', false, 75),
  (106, '76', 'together', 'pink',   '给一袋家庭垃圾做一次“去哪里”调查', '亲手分类并追问去向，环保才不只是记住几种颜色的垃圾桶。', '选少量干净、常见的废弃物，根据当地规则分类；不接触尖锐、腐败或有害垃圾。', '把最容易分错的三样物品画成一张家庭分类提示卡。', 'photo', false, 76),
  (244, '77', 'child',    'orange', '整理换季衣物，把合适的部分认真捐出', '在保留选择权的前提下整理和分享，能让孩子同时学习照顾物品与照顾别人。', '让孩子试穿并自主分组，清洗完好衣物后选择正规渠道；不要把破损物当作捐赠。', '在打包前写一张祝福卡放进去，不记录受赠者隐私。', 'photo', true, 77),
  (162, '78', 'together', 'green',  '把一件旧物改造成家里还会继续用的东西', '共同修补和改造，会让孩子看见创造不一定从购买新东西开始。', '从安全、容易处理的纸盒、旧布或容器中选一样，先画用途再分工制作；工具由成人把关。', '拍下旧物原样和改造后的实际使用场景。', 'photo', false, 78),
  (283, '79', 'together', 'pink',   '合作组装一件家里真正需要的小物', '读说明、分工、出错再重来，是一次很具体的合作和解决问题练习。', '选择适龄的玩具或简单家具，先一起看步骤；成人处理重物和危险工具，让孩子负责可完成的部分。', '记录一次装错后怎样发现并修正，以及完成后的合影。', 'photo', false, 79),
  (101, '80', 'together', 'orange', '从和面开始，包一顿形状各异的饺子', '一起做传统食物，手上的笨拙、笑声和味道会比成品是否漂亮更值得记住。', '按年龄分配和面、擀皮、放馅或捏边；生肉、刀具和热锅由成人负责，允许孩子发明形状。', '给每个人最有特点的饺子拍一张“出锅前后”对照照。', 'photo', false, 80),
  (279, '81', 'together', 'green',  '从称量材料开始，烤一盘共同完成的点心', '把配方变成香味的过程，会让数学、等待和合作都落在一次真实的成果里。', '选步骤简单的饼干或蛋糕，让孩子称量、搅拌和计时；烤箱及高温器具只由成人操作。', '拍下进烤箱前和出炉后的样子，再记录最出乎意料的一步。', 'photo', false, 81),
  (268, '82', 'child',    'pink',   '让孩子设计一款只属于这个夏天的水果冰棒', '从口味、颜色到名字都由孩子决定，一份小甜点也能成为完整的创造。', '准备适龄食材和模具，让孩子搭配并命名；注意过敏、卫生和冷冻等待时间。', '拍下配方卡和第一次脱模的表情。', 'photo', true, 82),
  (99,  '83', 'parent',   'orange', '包一次粽子，也讲讲你家怎样过端午', '节日不只是一种食物，家里的做法和讲法会慢慢成为孩子自己的文化记忆。', '根据家庭习惯做简化粽子，边做边讲端午故事和你小时候的过法；不同说法可以一起查证。', '录下孩子复述的“我们家端午故事”，不要求完全正确。', 'voice', true, 83),
  (155, '84', 'together', 'green',  '一起写一副真正想贴在家里的春联', '当新年的祝愿由全家共同想出，传统就从现成装饰变成了自己的表达。', '先说今年最想送给家人的祝福，再共同组成上下联；不会书法可以描字、画画或打印。', '拍下从草稿到贴上门的过程，并保存这一年的关键词。', 'photo', true, 84),
  (171, '85', 'together', 'pink',   '共同准备一顿简单野餐，去户外慢慢吃', '从准备到分享都一起完成，普通的一顿饭会因为地点和分工变成清楚的共同记忆。', '每个人负责一样食物或用品，选择允许野餐且安全的地方；带走全部垃圾，不追求复杂摆拍。', '饭后拍一张你们实际坐过的地方和收拾干净后的样子。', 'photo', true, 85),
  (117, '86', 'child',    'orange', '用大纸箱搭一个由孩子命名的秘密基地', '一个可进入的小空间，会装下孩子的想象，也让家长有机会按他的规则做客。', '收集干净纸箱，去掉订书钉等危险物；由孩子画设计、定名字和参观规则，成人协助加固。', '请小主人在基地里录一段导览，介绍最重要的角落。', 'video', false, 86),
  (132, '87', 'together', 'green',  '一起让一只风筝真正飞起来', '从一次次落地到终于迎风升起，合作、调整和欢呼会落在同一个清晰瞬间。', '选择开阔合法场地，远离电线、道路和雷雨；轮流放线、观察风向，不把失败归责给谁。', '录下风筝第一次稳定升空和你们当时的声音。', 'video', true, 87),
  (256, '88', 'together', 'pink',   '选一座适龄的小山，一起走到自己的终点', '共同判断体力、互相等待，比一定登顶更能让孩子理解坚持与照顾。', '选择正规、安全、难度合适的路线，准备水和防护；任何人不舒服都可以把当下位置当作终点。', '在你们共同决定停下或到达的地方拍照，记下彼此帮忙的一次。', 'photo', true, 88),
  (262, '89', 'together', 'orange', '完成一次有准备、有终点的亲子骑行', '一起看路、配速和照顾落后的人，会把运动变成真正的团队经历。', '按孩子能力选择安全绿道和距离，戴好头盔、检查车辆并约定停靠点；不在机动车道追求速度。', '保存路线和终点合影，再写下途中最想放弃或最开心的一刻。', 'photo', false, 89),
  (192, '90', 'together', 'green',  '上一次以安全和信任为目标的亲子游泳课', '在专业保护下适应水、学会求助和尊重边界，比“必须学会游泳”更重要。', '选择正规场馆和合格教练，家长全程在场；允许孩子按自己的节奏接触水，不强行憋气或下水。', '记录孩子今天愿意尝试的新动作，以及他明确说不的一件事。', 'text', false, 90),
  (221, '91', 'together', 'pink',   '一起当新手，学一项谁都不熟的运动', '当大人也会笨拙和失败，孩子更容易相信学习不是证明天赋，而是一起练习。', '选安全、适龄且双方愿意的运动，从体验课或最基础动作开始；不比较输赢，只互相给一个鼓励。', '录下你们各自第一次成功的小动作。', 'video', false, 91),
  (190, '92', 'together', 'orange', '跟着呼吸，完成一套不比赛的亲子瑜伽', '一起关注身体感受而不是谁更标准，能让亲子练习温和地回到自己和彼此。', '选择儿童友好的基础动作，在防滑垫上练习；疼痛就停止，不压腿、不互相强拉。', '结束后各自说一个身体最放松的地方并录下来。', 'voice', false, 92),
  (128, '93', 'together', 'green',  '一起学会一小段属于你们的舞', '同步一个节奏、一起忘动作再笑出来，会形成很有身体记忆的默契。', '由孩子选歌，挑二三十秒动作；可以改编，跳得不像也没关系，确保空间无障碍。', '录下最终版本，也保留一次跳错后继续完成的片段。', 'video', false, 93),
  (323, '94', 'together', 'pink',   '绑在一起走一次两人三足', '只有愿意听对方的节奏才能前进，这是一场把合作变得看得见的小游戏。', '在平整软地用宽布带松松固定相邻小腿，先慢走再挑战短距离；任何人不舒服立即停止。', '录下你们找到共同口令后最顺的一小段。', 'video', false, 94),
  (324, '95', 'together', 'orange', '用一只软球完成你们自己的连续传球纪录', '共同维护一个球不落地，目标会从“我赢你输”变成“一起比上次更默契”。', '选择安全空地和软球，从近距离抛接开始；由孩子决定挑战数字，落地就笑着重来。', '记录最终连续次数和达成时的庆祝动作。', 'video', false, 95),
  (349, '96', 'child',    'green',  '在家办一场孩子担任总导演的迷你音乐会', '当家人认真成为观众，孩子的表达会被当成一件值得准备和欣赏的事。', '由孩子定节目单、舞台和票券，可以唱歌、敲节奏或播放作品；表演与否由每个人自己决定。', '保存节目单，并录下谢幕和观众掌声。', 'video', false, 96),
  (338, '97', 'together', 'pink',   '轮流一句，写出一本只属于你们的童话', '接住对方意想不到的情节，会让想象力变成一次真正平等的合作。', '先共同定一个主角，然后轮流说或写一句，不否定上一句；最后一起画封面、起书名。', '录下完整故事，保留最让两个人都笑出来的转折。', 'voice', false, 97),
  (339, '98', 'together', 'orange', '设计一件藏着家庭暗号的 T 恤或帆布包', '把只有家人懂的符号穿在身上，会让共同身份变得可见又有趣。', '先画草稿，让每个人贡献一个元素；使用安全纺织笔或交给正规印制，不追求像商品一样完美。', '拍下草稿、成品和第一次使用时的合影。', 'photo', false, 98),
  (340, '99', 'together', 'green',  '做一面会继续长大的家庭回忆墙', '把共同经历放在日常可见之处，会提醒一家人：珍贵的生活一直在发生。', '选几张照片、票根或孩子的画，共同决定位置和说明；预留空白，约定以后慢慢增加。', '拍下第一版回忆墙，并各自指出最想讲给客人听的一格。', 'photo', false, 99),
  (245, '100','child',    'pink',   '让孩子选花，并共同插一瓶送给家里的花', '被允许按自己的眼光选择美，也能把一份普通的花变成孩子送给家的温柔表达。', '设定简单预算或使用自家可采的安全花材，让孩子选主花和颜色；不采受保护植物，修剪由成人协助。', '拍下孩子的第一版和最终作品，并请他给这瓶花起名字。', 'photo', false, 100)
)
INSERT INTO public.levels
  (num, perspective, tone, title, why, how, record, suggest, sealed, seal_until, sealed_on, seasonal, kid, sort_order)
SELECT
  num, perspective, tone, title, why, how, record, suggest, false, NULL, NULL, seasonal, NULL, sort_order
FROM curated
ON CONFLICT (num) DO UPDATE SET
  perspective = EXCLUDED.perspective,
  tone = EXCLUDED.tone,
  title = EXCLUDED.title,
  why = EXCLUDED.why,
  how = EXCLUDED.how,
  record = EXCLUDED.record,
  suggest = EXCLUDED.suggest,
  seasonal = EXCLUDED.seasonal,
  sort_order = EXCLUDED.sort_order;

COMMIT;
